import React, { useState, useEffect, Suspense, memo } from "react";
import { Outlet } from "react-router-dom";
import "./App.css";
import LoaderDialog from "./views/component/loader";
import { AuthContext } from "./context/AuthContext";
import { Toaster } from "react-hot-toast";
import {
  getServerConnectionState,
  getServerRetryInterval,
  probeServerConnection,
  subscribeToServerConnection,
} from "./lib/serverConnection";
import ServerConnectionScreen from "./views/component/server-status/ServerConnectionScreen";
import LeftLogo from "./assets/img/Left-logo.png";

function App() {
  const [token, setToken] = useState(null);
  const [role, setRole] = useState(null);
  const [user, setUser] = useState(null);
  const [serverState, setServerState] = useState(getServerConnectionState);
  const [initialProbeFinished, setInitialProbeFinished] = useState(false);

  useEffect(() => {
    const storedData = JSON.parse(localStorage.getItem("userData") || "{}");
    const savedToken = localStorage.getItem("token");

    if (storedData?.user && savedToken) {
      setToken(savedToken);
      setUser(storedData.user);
      setRole(storedData.user.role);
    } else {
      setToken(null);
      setUser(null);
      setRole(null);
    }
  }, []);

  useEffect(() => {
    const unsubscribe = subscribeToServerConnection(setServerState);

    probeServerConnection().finally(() => {
      setInitialProbeFinished(true);
    });

    return unsubscribe;
  }, []);

  useEffect(() => {
    const preloadImage = document.createElement("link");
    preloadImage.rel = "preload";
    preloadImage.as = "image";
    preloadImage.href = LeftLogo;
    preloadImage.fetchPriority = "high";
    document.head.appendChild(preloadImage);

    return () => {
      document.head.removeChild(preloadImage);
    };
  }, []);

  useEffect(() => {
    if (serverState.status === "up") {
      return undefined;
    }

    const intervalId = window.setInterval(() => {
      probeServerConnection();
    }, getServerRetryInterval());

    return () => {
      window.clearInterval(intervalId);
    };
  }, [serverState.status]);

  return (
    <Suspense fallback={<LoaderDialog loading={true} />}>
      <AuthContext.Provider value={{ token, setToken, user, role }}>
        {/* <AdminContext.Provider value={{}}> */}
        <Toaster position="bottom-right" />
        {serverState.status === "down" && initialProbeFinished ? (
          <ServerConnectionScreen
            isRetrying={false}
            lastCheckedAt={serverState.lastCheckedAt}
            onRetry={probeServerConnection}
          />
        ) : (
          <Outlet />
        )}
        {/* </AdminContext.Provider> */}
      </AuthContext.Provider>
    </Suspense>
  );
}

export default memo(App);
