import React, { lazy } from "react";
import ProtectedRoute from "./lib/ProtectedRoute";

const AdminLayout = lazy(() => import("./layouts/Admin"));
const AuthLayout = lazy(() => import("./layouts/Auth"));
const Unauthorized = lazy(() => import("./views/component/Unauthorized"));
const SignIn = lazy(() => import("./views/signIn/SignPage"));
const ForgotPassword = lazy(() => import("./views/forgetpass/ForgotPassword"));
const HomePage = lazy(() => import("./views/pages/HomePage"));
const Alarm = lazy(() => import("./views/pages/Alarm/Alarm"));
const Setting = lazy(() => import("./views/pages/Setting/Setting"));
const UserMgt = lazy(
  () => import("./views/pages/Managment/Usermgt/UserManagement"),
);
const SitesMgt = lazy(
  () => import("./views/pages/Managment/SitesMgt/SitesManagment"),
);
const Resistence = lazy(
  () => import("./views/pages/ResisteanceMonitoring/ResistanceTable"),
);
const Temperature = lazy(
  () => import("./views/pages/TemperatureMonitoring/TemperatureTable"),
);
const SitesProfile = lazy(
  () => import("./views/pages/Managment/SitesMgt/SitesProfile/sites-profile"),
);
const TechnicianProfile = lazy(
  () =>
    import("./views/pages/Managment/Usermgt/UserTabs/TechProfile/TechnicianProfile"),
);
const UserProfile = lazy(
  () =>
    import("./views/pages/Managment/Usermgt/UserTabs/UserProfile/UserProfile"),
);
const TestHomepage = lazy(() => import("./views/component/test-homepage"));

export const routes = [
  {
    element: <AuthLayout />,
    children: [
      { path: "/signIn", element: <SignIn /> },
      { path: "/forgot-password", element: <ForgotPassword /> },
      { path: "*", element: <Unauthorized /> },
    ],
  },
  {
    element: <ProtectedRoute />,
    children: [
      {
        element: <AdminLayout />,
        children: [
          {
            path: "/",
            element: <HomePage />,
          },
          {
            path: "/test",
            element: <TestHomepage />,
          },
          {
            path: "/dashboard",
            element: <HomePage />,
          },
          {
            path: "/resistance-monitoring",
            element: <Resistence />,
          },
          {
            path: "/sites-mgt",
            element: <SitesMgt />,
          },
          {
            path: "/user-management",
            element: <UserMgt />,
          },
          {
            path: "/temperature-monitoring",
            element: <Temperature />,
          },
          {
            path: "/alarm",
            element: <Alarm />,
          },
          {
            path: "/setting",
            element: <Setting />,
          },
          {
            path: "/sites-profile",
            element: <SitesProfile />,
          },
          {
            path: "/technician-profile",
            element: <TechnicianProfile />,
          },
          {
            path: "/user-profile",
            element: <UserProfile />,
          },
          {
            path: "*",
            element: <Unauthorized />,
          },
        ],
      },
    ],
  },
];
